// ── Processa cada lead e determina: mensagem a enviar + próximo status ─────
const response = $input.first().json;
const records  = response.records || [];

const NEXT_STATUS = {
  'Dia_1':     'Dia_2',
  'Dia_2':     'Dia_3',
  'Dia_3':     'Dia_4_Pitch',
  'Dia_4_Pitch': 'Proposta_Enviada'
};

// Mensagens por etapa — texto personalizado inserido antes de enviar
const MENSAGENS = {
  Dia_1: (nome, nicho) =>
    `Oi ${nome}! Tudo bem? 👋\n\n` +
    `Vi o perfil de vocês no Instagram — trabalham com ${nicho}, né? Adorei! ` +
    `Tenho acompanhado marcas do segmento e sempre fico curioso sobre os bastidores. ` +
    `Como tá sendo essa jornada?`,

  Dia_2: (nome, nicho) =>
    `${nome}, continuando nossa conversa... 😊\n\n` +
    `Trabalhei recentemente com uma empresa de ${nicho} e o que mais me surpreendeu foi ` +
    `como uma identidade visual consistente impactou diretamente nas vendas deles — ` +
    `clientes começaram a chegar por indicação só por parecer mais profissional. ` +
    `Vocês já passaram por isso?`,

  Dia_3: (nome, nicho) =>
    `Oi ${nome}! Uma pergunta rápida... 🤔\n\n` +
    `No ${nicho}, você sente que seus clientes reconhecem a marca de vocês ` +
    `ou ainda é pelo boca a boca mesmo? ` +
    `Pergunto porque é exatamente esse gap que costumo resolver. Seria ótimo entender o cenário de vocês.`,

  Dia_4_Pitch: (nome, nicho, pitchScript) =>
    pitchScript ||
    `${nome}, fui direto ao ponto: 🎯\n\n` +
    `Acredito que posso transformar a percepção da marca de vocês em ${nicho} com uma ` +
    `identidade visual que realmente converte. ` +
    `Tenho uma proposta personalizada. Posso apresentar em 15 minutos essa semana?`
};

const paraEnviar = [];
const paraDescartar = [];
const agora = Date.now();
const LIMITE_DIAS_INATIVO = 3; // dias sem avanço → Reprovado

for (const record of records) {
  const f      = record.fields || {};
  const status = f.Status;
  const nome   = (f.Nome_Empresa || f.Username || 'Olá').split(' ')[0];
  const nicho  = f.Nicho || 'seu segmento';
  const fone   = f.Telefone_WA;

  if (!fone) continue; // sem telefone, pula

  // Checa inatividade: se a última ação foi há mais de LIMITE_DIAS dias, descarta
  if (f.Data_Ultima_Acao) {
    const ultima = new Date(f.Data_Ultima_Acao).getTime();
    const diasParados = (agora - ultima) / 86400000;
    if (diasParados > LIMITE_DIAS_INATIVO) {
      paraDescartar.push({ record_id: record.id, username: f.Username, motivo: 'inativo_3d' });
      continue;
    }
  }

  const mensagem    = MENSAGENS[status](nome, nicho, f.Pitch_Script);
  const proximoStatus = NEXT_STATUS[status];

  paraEnviar.push({
    json: {
      record_id:      record.id,
      status_atual:   status,
      proximo_status: proximoStatus,
      telefone:       fone,
      mensagem,
      username:       f.Username
    }
  });
}

// Grava descartados no staticData para o nó de limpeza
$workflow.staticData.paraDescartar = paraDescartar;
$workflow.staticData.totalEnviados = 0;

console.log(`[MOD5] Para enviar: ${paraEnviar.length} | Para descartar (inativos): ${paraDescartar.length}`);

if (paraEnviar.length === 0) {
  return [{ json: { _sem_leads: true, descartados: paraDescartar.length } }];
}

return paraEnviar;

// Atualiza status para o próximo estágio e registra Data_Ultima_Acao
$workflow.staticData.totalEnviados = ($workflow.staticData.totalEnviados || 0) + 1;

return {
  json: {
    record_id:    $input.item.json.record_id,
    novo_status:  $input.item.json.proximo_status,
    username:     $input.item.json.username
  }
};

// Recupera lista de leads inativos do staticData
const paraDescartar = $workflow.staticData.paraDescartar || [];

if (paraDescartar.length === 0) {
  return [{ json: { _sem_descartados: true } }];
}

// Formata em lotes de 10 para PATCH bulk do Airtable
const records = paraDescartar.map(lead => ({
  id: lead.record_id,
  fields: {
    Status: 'Reprovado',
    Observacoes: `Descartado automaticamente — inativo por +3 dias (${new Date().toLocaleDateString('pt-BR')})`,
    Data_Ultima_Acao: new Date().toISOString()
  }
}));

console.log(`[MOD5-Limpeza] Descartando ${records.length} leads inativos.`);
return [{ json: { records, count: records.length } }];

const response = $input.first().json;
const records  = response.records || [];

if (records.length === 0) {
  return [{ json: { _sem_upsell: true } }];
}

const result = [];

for (const record of records) {
  const f    = record.fields || {};
  const nome = (f.Nome_Empresa || f.Username || 'Olá').split(' ')[0];
  const fone = f.Telefone_WA;

  if (!fone) continue;

  const mensagem =
    `Oi ${nome}! Tudo bem? 😊\n\n` +
    `Já faz um tempinho desde que entregamos o projeto de vocês, e fiquei pensando... ` +
    `Como a identidade visual nova está performando? Os clientes estão reagindo bem?\n\n` +
    `Tenho algumas ideias para a próxima fase (materiais, social media kit, apresentações). ` +
    `Vale uma conversa rápida essa semana? ☕`;

  result.push({
    json: {
      record_id: record.id,
      telefone:  fone,
      mensagem,
      nome
    }
  });
}

console.log(`[MOD5-Upsell] ${result.length} clientes para upsell hoje.`);

if (result.length === 0) {
  return [{ json: { _sem_upsell: true } }];
}

return result;

